// TimeZoneConfig.java — models the layered time-zone configuration
package com.nbi.db;

import java.util.*;

public class TimeZoneConfig {
    // The four layers where a default can be set.
    final String jvmUserTimezone;   // -Duser.timezone / TimeZone.setDefault
    final String jacksonTimezone;   // spring.jackson.time-zone
    final String hibernateJdbcTz;   // hibernate.jdbc.time_zone
    final String dockerTz;          // Docker TZ env var / /etc/localtime

    public TimeZoneConfig(String jvm, String jackson, String hibernate, String docker) {
            this.jvmUserTimezone = jvm;
            this.jacksonTimezone = jackson;
            this.hibernateJdbcTz = hibernate;
            this.dockerTz = docker;
    }

    // Consistent only if every layer agrees.
    public boolean isConsistent() {
        Set<String> zones = new HashSet<>(List.of(
            jvmUserTimezone, jacksonTimezone, hibernateJdbcTz, dockerTz));
        return zones.size() == 1;
    }

    public String report() {
        return "JVM user.timezone      = " + jvmUserTimezone + "\n" +
               "spring.jackson.time-zone= " + jacksonTimezone + "\n" +
               "hibernate.jdbc.time_zone= " + hibernateJdbcTz + "\n" +
               "Docker TZ              = " + dockerTz + "\n" +
               "=> consistent across layers? " + isConsistent();
    }
}
