// Demo.java — shows piecemeal (fragile) vs UTC-everywhere (deterministic)
package com.nbi.db;

import java.util.TimeZone;

public class Demo {
    public static void main(String[] args) {
        // JVM-layer default (legacy code path). Set ONCE at startup.
        // Equivalent to launching with: -Duser.timezone=UTC
        TimeZone.setDefault(TimeZone.getTimeZone("UTC"));
        System.out.println("JVM default (TimeZone.setDefault) = " + TimeZone.getDefault().getID());

        System.out.println("\n-- Fragile: layers disagree (the production bug) --");
        TimeZoneConfig mixed = new TimeZoneConfig("Asia/Kolkata", "UTC", "UTC", "America/New_York");
        System.out.println(mixed.report());

        System.out.println("\n-- Correct: UTC pinned at every layer --");
        TimeZoneConfig allUtc = new TimeZoneConfig("UTC", "UTC", "UTC", "UTC");
        System.out.println(allUtc.report());

        System.out.println("\nPresentation edge: convert UTC -> IST only when showing users.");
    }
}
